INSERT INTO `conf__tablas` (`tabla_id`, `tabla_nombre`, `tabla_descripcion`, `modulo_id`, `tabla_tipo_id`, `tabla_patron_id`, `tabla_estado_registro_id`)
SELECT s.`tabla_id`, s.`tabla_nombre`, s.`tabla_descripcion`, s.`modulo_id`, s.`tabla_tipo_id`, s.`tabla_patron_id`, s.`tabla_estado_registro_id` FROM `_sync_src` s WHERE 1=1
ON DUPLICATE KEY UPDATE
    `tabla_nombre` = VALUES(`tabla_nombre`),
    `tabla_descripcion` = VALUES(`tabla_descripcion`),
    `modulo_id` = VALUES(`modulo_id`),
    `tabla_tipo_id` = VALUES(`tabla_tipo_id`),
    `tabla_patron_id` = VALUES(`tabla_patron_id`),
    `tabla_estado_registro_id` = VALUES(`tabla_estado_registro_id`);

-- conf__tablas_estados_registros: 479 filas de local, modo upsert
