SELECT s.`perfil_id`, s.`modulo_id`, s.`perfil_nombre`, s.`tipo_operacion`, s.`tabla_estado_registro_id` FROM `_sync_src` s
WHERE NOT EXISTS (SELECT 1 FROM `conf__perfiles` x WHERE x.`perfil_id` <=> s.`perfil_id`);

-- conf__empresas_perfiles: 28 filas de local, modo insertar [empresa_id IN (1, 2)]
