INSERT INTO `conf__empresas_perfiles` (`empresa_perfil_id`, `empresa_id`, `modulo_id`, `perfil_id_base`, `empresa_perfil_nombre`, `tabla_estado_registro_id`)
SELECT s.`empresa_perfil_id`, s.`empresa_id`, s.`modulo_id`, s.`perfil_id_base`, s.`empresa_perfil_nombre`, s.`tabla_estado_registro_id` FROM `_sync_src` s
WHERE NOT EXISTS (SELECT 1 FROM `conf__empresas_perfiles` x WHERE x.`empresa_perfil_id` <=> s.`empresa_perfil_id`) AND (EXISTS (SELECT 1 FROM conf__empresas_modulos em WHERE em.empresa_id = s.empresa_id AND em.modulo_id = s.modulo_id AND em.tabla_estado_registro_id = 1));

-- conf__empresas_perfiles: perfil base de Gestion (201-208) de los perfiles que ya existen; el nombre no se toca
UPDATE conf__empresas_perfiles SET perfil_id_base = 201 WHERE empresa_perfil_id = 8 AND empresa_id = 2 AND perfil_id_base <=> 3;
UPDATE conf__empresas_perfiles SET perfil_id_base = 202 WHERE empresa_perfil_id = 12 AND empresa_id = 2 AND perfil_id_base <=> 4;

