INSERT INTO `conf__perfiles_funciones` (`perfil_id`, `pagina_funcion_id`, `asignado`, `fecha_asignacion`)
SELECT s.`perfil_id`, s.`pagina_funcion_id`, s.`asignado`, s.`fecha_asignacion` FROM `_sync_src` s
WHERE NOT EXISTS (SELECT 1 FROM `conf__perfiles_funciones` x WHERE x.`perfil_id` <=> s.`perfil_id` AND x.`pagina_funcion_id` <=> s.`pagina_funcion_id`);

