UPDATE `_sync_src` SET `tabla_estado_registro_id` = IF(impuesto_tipo_id IN (6, 14, 15, 16, 17, 22), 2, tabla_estado_registro_id);
UPDATE `gestion__empresas_impuestos_config` x JOIN `_sync_src` s ON x.`empresa_impuesto_config_id` = s.`empresa_impuesto_config_id`
SET
    x.`impuesto_tipo_id` = IF(x.`impuesto_tipo_id` IS NULL OR x.`impuesto_tipo_id` IN ('', '0'), s.`impuesto_tipo_id`, x.`impuesto_tipo_id`),
    x.`jurisdiccion_id` = IF(x.`jurisdiccion_id` IS NULL OR x.`jurisdiccion_id` IN ('', '0'), s.`jurisdiccion_id`, x.`jurisdiccion_id`),
    x.`condicion_fiscal_id` = IF(x.`condicion_fiscal_id` IS NULL OR x.`condicion_fiscal_id` IN ('', '0'), s.`condicion_fiscal_id`, x.`condicion_fiscal_id`),
    x.`cont_cuenta_id` = IF(x.`cont_cuenta_id` IS NULL OR x.`cont_cuenta_id` IN ('', '0'), s.`cont_cuenta_id`, x.`cont_cuenta_id`),
    x.`base_calculo` = IF(x.`base_calculo` IS NULL OR x.`base_calculo` IN ('', '0'), s.`base_calculo`, x.`base_calculo`),
    x.`alicuota` = IF(x.`alicuota` IS NULL OR x.`alicuota` IN ('', '0'), s.`alicuota`, x.`alicuota`),
    x.`minimo_imponible` = IF(x.`minimo_imponible` IS NULL OR x.`minimo_imponible` IN ('', '0'), s.`minimo_imponible`, x.`minimo_imponible`),
    x.`monto_fijo` = IF(x.`monto_fijo` IS NULL OR x.`monto_fijo` IN ('', '0'), s.`monto_fijo`, x.`monto_fijo`),
    x.`tipo_calculo` = IF(x.`tipo_calculo` IS NULL OR x.`tipo_calculo` IN ('', '0'), s.`tipo_calculo`, x.`tipo_calculo`),
    x.`numero_agente` = IF(x.`numero_agente` IS NULL OR x.`numero_agente` IN ('', '0'), s.`numero_agente`, x.`numero_agente`),
    x.`criterio_territorial` = IF(x.`criterio_territorial` IS NULL OR x.`criterio_territorial` IN ('', '0'), s.`criterio_territorial`, x.`criterio_territorial`),
    x.`importe_minimo_percepcion` = IF(x.`importe_minimo_percepcion` IS NULL OR x.`importe_minimo_percepcion` IN ('', '0'), s.`importe_minimo_percepcion`, x.`importe_minimo_percepcion`),
    x.`arca_tributo_id` = IF(x.`arca_tributo_id` IS NULL OR x.`arca_tributo_id` IN ('', '0'), s.`arca_tributo_id`, x.`arca_tributo_id`),
    x.`formato_padron` = IF(x.`formato_padron` IS NULL OR x.`formato_padron` IN ('', '0'), s.`formato_padron`, x.`formato_padron`),
    x.`formato_ddjj` = IF(x.`formato_ddjj` IS NULL OR x.`formato_ddjj` IN ('', '0'), s.`formato_ddjj`, x.`formato_ddjj`),
    x.`codigo_jurisdiccion_cm` = IF(x.`codigo_jurisdiccion_cm` IS NULL OR x.`codigo_jurisdiccion_cm` IN ('', '0'), s.`codigo_jurisdiccion_cm`, x.`codigo_jurisdiccion_cm`),
    x.`codigo_regimen_ddjj` = IF(x.`codigo_regimen_ddjj` IS NULL OR x.`codigo_regimen_ddjj` IN ('', '0'), s.`codigo_regimen_ddjj`, x.`codigo_regimen_ddjj`),
    x.`fuente_alicuota` = IF(x.`fuente_alicuota` IS NULL OR x.`fuente_alicuota` IN ('', '0'), s.`fuente_alicuota`, x.`fuente_alicuota`),
    x.`sin_dato_accion` = IF(x.`sin_dato_accion` IS NULL OR x.`sin_dato_accion` IN ('', '0'), s.`sin_dato_accion`, x.`sin_dato_accion`),
    x.`integracion_empresa_id` = IF(x.`integracion_empresa_id` IS NULL OR x.`integracion_empresa_id` IN ('', '0'), s.`integracion_empresa_id`, x.`integracion_empresa_id`),
